#!/usr/bin/env bash
# Pull or publish the status-data branch into ./status. Publishing replaces the branch with one commit.
set -euo pipefail
url="https://x-access-token:${GH_TOKEN}@github.com/${GITHUB_REPOSITORY}.git"
if [ "$1" = pull ]; then
  rm -rf status
  if git ls-remote --exit-code --heads "$url" status-data >/dev/null 2>&1; then
    git clone --quiet --depth 1 --branch status-data "$url" status
  else
    mkdir -p status
  fi
else
  cd status
  rm -rf .git
  git init --quiet -b status-data
  git config user.name "fynx-status-monitor"
  git config user.email "actions@users.noreply.github.com"
  printf '%s\n' "# FYNX API status data" "" "Generated by .github/workflows/api-status.yml on main. Read by /api/status.html. Do not edit." > README.md
  git add -A
  git commit --quiet -m "Status data $(date -u +%Y-%m-%dT%H:%MZ)"
  git push --quiet --force "$url" status-data
fi
